// ---- parse.js ----
// The device's text formats, read into plain values. Pure functions with no DOM, so tests/test_web.mjs can run them
// under Node. Formats: DESIGN.md section 7 and components/precision_feeder/feeder_text.cpp. Every parser returns
// null (or an empty list) for text it does not recognise; the caller then shows the raw text instead.

const WEEKDAYS = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];

/** "a=1;b=x" -> {a: '1', b: 'x'} (BLE Info, BLE Session). */
function parseKV(text) {
  const out = {};
  for (const part of String(text || '').split(';')) {
    const i = part.indexOf('=');
    if (i > 0) out[part.slice(0, i).trim()] = part.slice(i + 1).trim();
  }
  return out;
}

/** A "; "-separated list where "none" means empty (Faults, Recent Feeds, One-shot Feeds). */
function parseList(text) {
  const t = String(text || '').trim();
  if (!t || t === 'none') return [];
  return t.split(';').map(s => s.trim()).filter(Boolean);
}

/** "Thu 2026-10-15 17:30" (the device's local time, as format_local_ writes it) -> parts, or null. */
function parseLocalDateTime(text) {
  const m = /^(?:(\w{3}) )?(\d{4})-(\d{2})-(\d{2}) (\d{2}):(\d{2})/.exec(String(text || '').trim());
  if (!m) return null;
  const [, weekday, y, mo, d, hh, mm] = m;
  return { weekday: weekday || null, year: +y, month: +mo, day: +d, hour: +hh, minute: +mm,
           date: `${y}-${mo}-${d}`, time: `${hh}:${mm}` };
}

/** "Thu 2026-10-15 17:30 -05:00" (Device Time) -> parts plus the UTC offset in minutes, or null. */
function parseDeviceTime(text) {
  const t = String(text || '').trim();
  const base = parseLocalDateTime(t);
  const m = /([+-])(\d{2}):(\d{2})$/.exec(t);
  if (!base || !m) return null;
  const offsetMin = (m[1] === '-' ? -1 : 1) * (+m[2] * 60 + +m[3]);
  return Object.assign(base, { offset: `${m[1]}${m[2]}:${m[3]}`, offsetMin });
}

/** A wall-clock time on the device as the browser's locale writes times (17:30 or 5:30 PM). No timezone maths:
 *  the device already gives local time, so it is formatted as if it were UTC. */
function formatClock(hour, minute, locale) {
  const d = new Date(Date.UTC(2000, 0, 1, hour, minute));
  return d.toLocaleTimeString(locale, { hour: 'numeric', minute: '2-digit', timeZone: 'UTC' });
}

/** A date on the device as "Thu 15 Oct" in the browser's language. */
function formatDate(parts, locale) {
  const d = new Date(Date.UTC(parts.year, parts.month - 1, parts.day, 12));
  return d.toLocaleDateString(locale, { weekday: 'short', day: 'numeric', month: 'short', timeZone: 'UTC' });
}

/** Seconds as "3 d 4 h", "2 h 5 min", "12 min" or "40 s". */
function formatDuration(seconds) {
  if (seconds == null || !isFinite(seconds) || seconds < 0) return '';
  const s = Math.floor(seconds);
  const d = Math.floor(s / 86400), h = Math.floor(s % 86400 / 3600), m = Math.floor(s % 3600 / 60);
  if (d) return `${d} d ${h} h`;
  if (h) return `${h} h ${m} min`;
  if (m) return `${m} min`;
  return `${s} s`;
}

/** A log line from /events ("\x1b[0;32m[I][tag:042]: text\x1b[0m") -> {level, tag, text}. */
function parseLogLine(line) {
  const clean = String(line || '').replace(/\x1b\[[0-9;]*m/g, '');
  const m = /^\[([EWICDV])\]\[([^\]]*)\]:?\s?(.*)$/s.exec(clean);
  if (!m) return { level: '', tag: '', text: clean };
  return { level: m[1], tag: m[2].replace(/:\d+$/, ''), text: m[3] };
}

// ---- store.js ----
// The connection to the device and everything it has told us. One EventSource on /events: ESPHome's web server
// sends a "ping" with the device's title and uptime, then every entity of the build with full detail (name,
// limits, options, ...), then a "state" event whenever one changes, "log" lines, and a "ping" every 10 seconds.
// The app reads the device only through here, and changes it only through api.js.

const LOG_MAX = 300;
const STALE_MS = 25000;  // no ping for this long: the connection is dead even if the browser has not noticed

const store = {
  entities: new Map(),  // "domain/Name" -> the latest JSON the device sent for it (full detail kept)
  title: '',
  status: 'connecting',  // connecting | online | offline
  everOnline: false,
  lastNewEntity: 0,      // Date.now() when an entity was last seen for the first time
  logLines: [],          // {at, text}, newest last
  logCount: 0,           // lines received in total (so a view can tell which ones are new)
  uptimeS: null,
  uptimeAt: 0,
  _subs: new Set(),
  _watchers: new Set(),
  _changed: new Set(),
  _timer: 0,
  _es: null,
  _retry: 0,
  _lastMessage: 0,

  get(id) { return this.entities.get(id); },
  has(id) { return this.entities.has(id); },
  /** The value as text (text sensors, selects, texts), '' if unknown. */
  text(id) {
    const e = this.entities.get(id);
    return e ? String(e.value ?? e.state ?? '') : '';
  },
  /** The value as a number (sensors, numbers), NaN if unknown. */
  num(id) {
    const e = this.entities.get(id);
    if (!e || e.value === null || e.value === undefined) return NaN;
    return typeof e.value === 'number' ? e.value : parseFloat(e.value);
  },
  /** Binary sensors and switches: true, false, or undefined if not in this build. */
  bool(id) {
    const e = this.entities.get(id);
    return e ? e.value === true : undefined;
  },
  /** Seconds since the device booted, counted on from its last ping. */
  uptime() {
    return this.uptimeS === null ? null : this.uptimeS + (Date.now() - this.uptimeAt) / 1000;
  },

  /** fn(changed: Set of ids, plus "*status", "*ping", "*log") after each burst of updates. Returns unsubscribe. */
  subscribe(fn) {
    this._subs.add(fn);
    return () => this._subs.delete(fn);
  },
  /** fn(id) at once for every update (for code waiting on one entity). Returns unwatch. */
  watch(fn) {
    this._watchers.add(fn);
    return () => this._watchers.delete(fn);
  },

  _mark(id) {
    this._changed.add(id);
    for (const w of [...this._watchers]) w(id);
    if (!this._timer) this._timer = setTimeout(() => this._flush(), 40);
  },
  _flush() {
    this._timer = 0;
    const changed = this._changed;
    this._changed = new Set();
    for (const fn of [...this._subs]) fn(changed);
  },
  _setStatus(status) {
    if (this.status === status) return;
    this.status = status;
    if (status === 'online') this.everOnline = true;
    this._mark('*status');
  },

  connect() {
    if (this._es) this._es.close();
    const es = new EventSource('/events');
    this._es = es;
    this._lastMessage = Date.now();
    const alive = () => { this._lastMessage = Date.now(); this._retry = 0; this._setStatus('online'); };
    es.onopen = alive;
    es.onerror = () => {
      if (this._es !== es) return;
      // Reconnect ourselves: ESPHome asks browsers to wait 30 s, too long for someone looking at the page.
      es.close();
      this._es = null;
      this._setStatus('offline');
      setTimeout(() => this.connect(), Math.min(10000, 1000 * 2 ** this._retry++));
    };
    es.addEventListener('ping', ev => {
      alive();
      try {
        const d = JSON.parse(ev.data);
        if (typeof d.title === 'string') this.title = d.title;
        if (typeof d.uptime === 'number') {
          this.uptimeS = d.uptime;
          this.uptimeAt = Date.now();
        }
      } catch (err) { /* a ping we cannot read changes nothing */ }
      this._mark('*ping');
    });
    es.addEventListener('state', ev => {
      alive();
      let d;
      try { d = JSON.parse(ev.data); } catch (err) { return; }
      // ESPHome 2026.x ids are "domain/Name"; build one from the detail if an older format ever arrives.
      let id = d.id;
      if (typeof id !== 'string' || !id.includes('/')) id = d.domain && d.name ? `${d.domain}/${d.name}` : null;
      if (!id) return;
      const prev = this.entities.get(id);
      if (prev) Object.assign(prev, d);
      else {
        this.entities.set(id, d);
        this.lastNewEntity = Date.now();
      }
      this._mark(id);
    });
    es.addEventListener('log', ev => {
      alive();
      this.logLines.push({ at: Date.now(), text: ev.data });
      this.logCount++;
      if (this.logLines.length > LOG_MAX) this.logLines.shift();
      this._mark('*log');
    });
  },

  start() {
    this.connect();
    setInterval(() => {
      if (this._es && this.status === 'online' && Date.now() - this._lastMessage > STALE_MS) {
        this._es.onerror();  // treat silence as a dropped connection
      }
    }, 5000);
  },
};

// ---- api.js ----
// Changes to the device: ESPHome's web server actions (POST /<domain>/<name>/<action>), one at a time, so the
// device's few HTTP sockets are never flooded and writes arrive in the order they were made. The device answers
// 200 as soon as it has queued an action; whether it took effect shows up as the entity's next state, which the
// firmware publishes within about a second (waitFor). Nothing here decides anything about feeding: the device's
// feed guard does, for every request.

const api = {
  _queue: Promise.resolve(),

  /** Run an action on an entity, after every earlier one. Rejects if the device refuses or cannot be reached. */
  call(id, action, params) {
    const slash = id.indexOf('/');
    const domain = id.slice(0, slash), name = id.slice(slash + 1);
    const query = params ? Object.entries(params)
      .map(([k, v]) => `${encodeURIComponent(k)}=${encodeURIComponent(String(v))}`).join('&') : '';
    const url = `/${domain}/${encodeURIComponent(name)}/${action}${query ? '?' + query : ''}`;
    // From the origin, not relative: a page opened as http://user:pass@feeder/ would otherwise put the credentials
    // into every request URL, which browsers refuse. The browser still sends the cached credentials.
    const run = () => fetch(location.origin + url, { method: 'POST' }).then(r => {
      if (!r.ok) throw new Error(r.status === 404 ? 'This build does not have that control.' : `The feeder answered ${r.status}.`);
    }, () => { throw new Error('The feeder could not be reached.'); });
    const done = this._queue.then(run, run);
    this._queue = done.catch(() => {});
    return done;
  },
  press(id) { return this.call(id, 'press'); },
  turn(id, on) { return this.call(id, on ? 'turn_on' : 'turn_off'); },
  setNumber(id, value) { return this.call(id, 'set', { value }); },
  setOption(id, option) { return this.call(id, 'set', { option }); },
  setText(id, value) { return this.call(id, 'set', { value }); },

  /** Resolve with the entity once pred(entity) holds (now or after an update); reject after `ms`. */
  waitFor(id, pred, ms = 4000) {
    return new Promise((resolve, reject) => {
      let timer = 0;
      const unwatch = store.watch(changed => {
        if (changed !== id) return;
        const e = store.get(id);
        if (e && pred(e)) finish(e);
      });
      const finish = e => { clearTimeout(timer); unwatch(); resolve(e); };
      const now = store.get(id);
      if (now && pred(now)) return finish(now);
      timer = setTimeout(() => { unwatch(); reject(new Error('The feeder did not confirm the change.')); }, ms);
    });
  },

  /** Set a number, select or text, then wait until the device reports the new value. */
  setAndConfirm(id, value, ms = 4000) {
    const e = store.get(id);
    if (!e) return Promise.reject(new Error('This build does not have that setting.'));
    let write, same;
    if (e.domain === 'number' || id.startsWith('number/')) {
      const step = parseFloat(e.step) || 1;
      write = this.setNumber(id, value);
      same = x => Math.abs(parseFloat(x.value) - parseFloat(value)) < step / 2;
    } else if (id.startsWith('select/')) {
      write = this.setOption(id, value);
      same = x => x.value === value;
    } else {
      write = this.setText(id, value);
      same = x => x.value === value;
    }
    return write.then(() => this.waitFor(id, same, ms));
  },
};

// ---- ui.js ----
// DOM helpers and the small widgets every page shares. No framework: pages build their DOM once with h() and
// update the parts that change.

/** Pages register here: PAGES.<tab id> = {mount(el, route), update(changed), unmount()}. */
const PAGES = {};

/** h('div', {class: 'x', onclick: fn}, child, 'text', [more]) -> an element. */
function h(tag, props, ...children) {
  const el = document.createElement(tag);
  for (const [k, v] of Object.entries(props || {})) {
    if (v === null || v === undefined || v === false) continue;
    if (k === 'class') el.className = v;
    else if (k.startsWith('on') && typeof v === 'function') el.addEventListener(k.slice(2).toLowerCase(), v);
    else if (k === 'value') el.value = v;
    else if (k === 'checked') el.checked = v;
    else el.setAttribute(k, v === true ? '' : v);
  }
  append(el, children);
  return el;
}

/** Append children: nodes, text, or (nested) arrays of them; null, undefined and false are skipped. */
function append(el, ...children) {
  for (const c of children.flat(Infinity)) {
    if (c === null || c === undefined || c === false) continue;
    el.appendChild(c instanceof Node ? c : document.createTextNode(String(c)));
  }
  return el;
}

function clear(el) {
  while (el.firstChild) el.removeChild(el.firstChild);
  return el;
}

/** Set an element's text only when it changes (keeps the DOM quiet). */
function setText(el, text) {
  const t = text === null || text === undefined ? '' : String(text);
  if (el.textContent !== t) el.textContent = t;
}

