function icon(name, size = 20) {
  const ns = 'http://www.w3.org/2000/svg';
  const svg = document.createElementNS(ns, 'svg');
  svg.setAttribute('viewBox', '0 0 24 24');
  svg.setAttribute('width', size);
  svg.setAttribute('height', size);
  svg.setAttribute('aria-hidden', 'true');
  svg.setAttribute('class', 'icon');
  const path = document.createElementNS(ns, 'path');
  path.setAttribute('d', ICONS[name] || ICONS.info);
  svg.appendChild(path);
  return svg;
}

// ---- toasts ----
function toast(message, kind = 'info', ms = 4000) {
  const box = document.getElementById('toasts');
  if (!box) return;
  const el = h('div', { class: `toast toast-${kind}`, role: kind === 'error' ? 'alert' : 'status' },
               icon(kind === 'error' ? 'alert' : kind === 'ok' ? 'check' : 'info', 18), h('span', {}, message));
  box.appendChild(el);
  setTimeout(() => {
    el.classList.add('toast-out');
    setTimeout(() => el.remove(), 300);
  }, ms);
}

/** Toast an error from a rejected api call. */
function toastError(err) {
  toast(err && err.message ? err.message : String(err), 'error', 6000);
}

// ---- dialogs ----
/** A modal question. body: text or nodes. Resolves true for OK, false for Cancel or Escape. */
function confirmDialog({ title, body, ok = 'OK', cancel = 'Cancel', danger = false }) {
  return new Promise(resolve => {
    const dlg = h('dialog', { class: 'dialog', 'aria-labelledby': 'dlg-title' },
      h('form', { method: 'dialog' },
        h('h2', { id: 'dlg-title' }, title),
        h('div', { class: 'dialog-body' }, typeof body === 'string' ? h('p', {}, body) : body),
        h('div', { class: 'dialog-actions' },
          h('button', { value: 'cancel', class: 'btn' }, cancel),
          h('button', { value: 'ok', class: danger ? 'btn btn-danger' : 'btn btn-primary' }, ok))));
    dlg.addEventListener('close', () => {
      resolve(dlg.returnValue === 'ok');
      dlg.remove();
    });
    document.body.appendChild(dlg);
    dlg.showModal();
  });
}

// ---- layout helpers ----
function card(title, ...children) {
  return h('section', { class: 'card' }, title ? h('h2', { class: 'card-title' }, title) : null, ...children);
}

/** A label / value row; returns {row, value} so the value can be updated. */
function row(label, value = '') {
  const v = h('span', { class: 'row-value' }, value);
  return { row: h('div', { class: 'row' }, h('span', { class: 'row-label' }, label), v), value: v };
}

/** A label row whose value is kept in step with an entity: fn(store) -> text. Returns an updater. */
function boundRow(parent, label, fn) {
  const r = row(label);
  parent.appendChild(r.row);
  return () => setText(r.value, fn());
}

// ---- controls for any entity (the All entities list; reused by settings pages) ----

/** A control for entity `id` that writes through api and reports the outcome; null for read-only entities. */
function entityControl(id) {
  const e = store.get(id);
  if (!e) return null;
  const domain = e.domain || id.slice(0, id.indexOf('/'));
  const label = e.name || id;
  if (domain === 'button') {
    return h('button', { class: 'btn btn-small', onclick: async () => {
      if (!await confirmDialog({ title: `Press "${label}"?`, body: 'This acts on the feeder straight away.', ok: 'Press' })) return;
      api.press(id).then(() => toast(`Pressed ${label}`, 'ok'), toastError);
    } }, 'Press');
  }
  if (domain === 'switch') {
    const btn = h('button', { class: 'btn btn-small', role: 'switch', onclick: () => {
      const on = !store.bool(id);
      api.turn(id, on).then(() => api.waitFor(id, x => x.value === on)).catch(toastError);
    } });
    btn._update = () => {
      const on = store.bool(id);
      btn.setAttribute('aria-checked', on ? 'true' : 'false');
      setText(btn, on ? 'On' : 'Off');
      btn.classList.toggle('btn-on', !!on);
    };
    btn._update();
    return btn;
  }
  if (domain === 'select') {
    const sel = h('select', { class: 'input', 'aria-label': label, onchange: () => {
      api.setAndConfirm(id, sel.value).catch(err => { toastError(err); sel._update(); });
    } }, (e.option || []).map(o => h('option', { value: o }, o)));
    sel._update = () => { if (document.activeElement !== sel) sel.value = store.text(id); };
    sel._update();
    return sel;
  }
  if (domain === 'number' || domain === 'text') {
    const isNum = domain === 'number';
    const input = h('input', isNum
      ? { class: 'input input-num', type: 'number', inputmode: 'decimal', min: e.min_value, max: e.max_value,
          step: e.step, 'aria-label': label }
      : { class: 'input', type: 'text', maxlength: e.max_length, 'aria-label': label });
    const err = h('span', { class: 'field-error', 'aria-live': 'polite' });
    const save = () => {
      setText(err, '');
      const v = input.value.trim();
      if (isNum) {
        const x = parseFloat(v), lo = parseFloat(e.min_value), hi = parseFloat(e.max_value);
        if (v === '' || isNaN(x)) return setText(err, 'Enter a number');
        if (x < lo || x > hi) return setText(err, `From ${e.min_value} to ${e.max_value}`);
      }
      api.setAndConfirm(id, isNum ? parseFloat(v) : v)
        .then(() => toast(`${label} saved`, 'ok'), x => { toastError(x); input._update(true); });
    };
    input.addEventListener('keydown', ev => { if (ev.key === 'Enter') save(); });
    input.addEventListener('input', () => setText(err, ''));
    input._update = force => {
      if (!force && document.activeElement === input) return;
      const n = parseFloat(store.get(id).value);
      input.value = isNum ? (isNaN(n) ? '' : n) : store.text(id);
    };
    input._update();
    const wrap = h('span', { class: 'field' }, input,
                   e.uom ? h('span', { class: 'unit' }, e.uom) : null,
                   h('button', { class: 'btn btn-small', onclick: save }, 'Set'), err);
    wrap._update = () => input._update();
    return wrap;
  }
  return null;
}

// ---- banners.js ----
// The banner under the header: the most important thing wrong right now, with what you can do about it. One at a
// time, most severe first. Everything here comes from what the device reports (Tray State, Faults, Clock Valid,
// Hold, ...); the app never works out a fault for itself.

/** Before loading food: explain, then press Tray Reload. Shared with the Dashboard. */
async function trayReloadFlow() {
  const pause = store.num(E.reloadPause);
  const ok = await confirmDialog({
    title: 'Reload the tray?',
    body: h('div', {},
      h('p', {}, 'Press this before you load food. The tray turns back to the closed slot, so nothing can fall out ' +
                 'while you fill it, and all 6 portions count as available again.'),
      h('p', {}, isNaN(pause) || pause === 0
        ? 'Scheduled feeding carries on straight away.'
        : `Scheduled feeding pauses for ${pause} min while you load it. Feeds due in that time are skipped, not made up.`)),
    ok: 'Reload tray',
  });
  if (!ok) return;
  api.press(E.trayReload).then(() => toast('Tray going back to the closed slot', 'ok'), toastError);
}

/** Turn calibration mode off, which saves the offsets. */
function finishCalibration() {
  api.turn(E.calibrationMode, false)
    .then(() => api.waitFor(E.calibrationMode, x => x.value === false))
    .then(() => toast('Calibration saved', 'ok'), toastError);
}

/** The faults the banners below already explain, so they are not listed twice. */
const COVERED_FAULTS = ['clock not set', 'tray position unknown', 'tray empty', 'next feed needs more portions'];

function currentBanner() {
  if (store.everOnline && store.status !== 'online') {
    return { kind: 'neutral', icon: 'wifiOff', title: 'Connection lost',
             text: 'Reconnecting… The feeder keeps running on its own schedule.' };
  }
  if (!store.has(E.trayState)) return null;
  const tray = store.text(E.trayState);
  if (tray === 'unknown') {
    return { kind: 'danger', icon: 'alert', title: 'Tray position unknown',
             text: 'Feeding is off until you tell the feeder where the tray is, or reload it.',
             actions: [
               store.has(E.declarePosition) && PAGES.maintenance
                 ? { label: 'Recover position', run: () => { location.hash = '#maintenance/recover'; } } : null,
               { label: 'Tray reload', run: trayReloadFlow },
             ] };
  }
  if (tray === 'calibrating') {
    return { kind: 'warning', icon: 'tune', title: 'Calibration mode is on', text: 'All feeds are refused until you finish.',
             actions: store.has(E.calibrationMode) ? [{ label: 'Finish and save', run: finishCalibration }] : [] };
  }
  if (tray === 'empty') {
    return { kind: 'danger', icon: 'bowl', title: 'Tray empty',
             text: 'Reload the tray, then load food.', actions: [{ label: 'Tray reload', run: trayReloadFlow }] };
  }
  if (store.bool(E.clockValid) === false) {
    return { kind: 'warning', icon: 'clock', title: 'Clock not set',
             text: 'Scheduled feeds wait until the feeder knows the time. Feeding by hand still works.' };
  }
  if (store.bool(E.needsFood)) {
    return { kind: 'warning', icon: 'fish', title: 'The next feed needs more than remains',
             text: `${store.num(E.portionsRemaining)} left. Refill before ${store.text(E.nextFeed)}.`,
             actions: [{ label: 'Tray reload', run: trayReloadFlow }] };
  }
  const hold = store.text(E.hold);
  if (hold && hold !== 'none') {
    return { kind: 'info', icon: 'pause', title: 'Scheduled feeding on hold',
             text: `${hold[0].toUpperCase()}${hold.slice(1)}. Missed feeds are skipped, not made up.`,
             actions: store.has(E.cancelHold) ? [{ label: 'Resume now', run: () => api.press(E.cancelHold)
               .then(() => toast('Scheduled feeding resumed', 'ok'), toastError) }] : [] };
  }
  const other = parseList(store.text(E.faults)).filter(f => !COVERED_FAULTS.some(c => f.startsWith(c)));
  if (other.length) {
    return { kind: 'warning', icon: 'alert', title: other.length === 1 ? 'One thing to check' : `${other.length} things to check`,
             list: other.map(f => f[0].toUpperCase() + f.slice(1)) };
  }
  return null;
}

const banners = {
  el: null,
  key: '',
  mount(el) { this.el = el; },
  update() {
    const b = currentBanner();
    const key = b ? JSON.stringify([b.kind, b.title, b.text, b.list, (b.actions || []).filter(Boolean).map(a => a.label)]) : '';
    if (key === this.key) return;
    this.key = key;
    clear(this.el);
    if (!b) return;
    this.el.appendChild(h('div', { class: `banner banner-${b.kind}`, role: b.kind === 'danger' ? 'alert' : 'status' },
      icon(b.icon, 22),
      h('div', { class: 'banner-body' },
        h('strong', {}, b.title),
        b.text ? h('p', {}, b.text) : null,
        b.list ? h('ul', {}, b.list.map(f => h('li', {}, f))) : null,
        (b.actions || []).filter(Boolean).length
          ? h('div', { class: 'banner-actions' }, b.actions.filter(Boolean).map(a => h('button', { class: 'btn btn-small', onclick: a.run }, a.label)))
          : null)));
  },
};

// ---- pages/diagnostics.js ----
// Diagnostics: always present. System and clock, network and memory (when those packages are built in), the live
// log, and every entity the device reports with a control for each: the debug view, and the fallback for anything
// no other page shows.

const DOMAIN_TITLES = {
  sensor: 'Sensors', binary_sensor: 'Binary sensors', text_sensor: 'Text sensors', button: 'Buttons',
  switch: 'Switches', select: 'Selects', number: 'Numbers', text: 'Text inputs',
};
const LEVELS = { E: 0, W: 1, I: 2, C: 2, D: 3, V: 4 };

PAGES.diagnostics = {
  mount(root) {
    this.updaters = [];
    this.timer = setInterval(() => this.updateSystem(), 1000);

    // System
    const sys = card('System');
    const add = (label, fn) => this.updaters.push(boundRow(sys, label, fn));
    add('Firmware', () => store.text(E.firmware) || 'unknown');
    add('Device name', () => store.title || location.hostname);
    add('Running for', () => formatDuration(store.uptime()));
    if (store.has(E.deviceTime)) {
      add('Device time', () => {
        const t = parseDeviceTime(store.text(E.deviceTime));
        return t ? `${formatDate(t)} ${formatClock(t.hour, t.minute)} (UTC${t.offset})` : store.text(E.deviceTime);
      });
    }
    add('Clock', () => {
      if (store.bool(E.clockValid) === false) return 'not set';
      const age = store.num(E.clockAge);
      return [store.text(E.timeSource), isNaN(age) ? '' : `synced ${formatDuration(age * 60) || 'just now'} ago`]
        .filter(Boolean).join(', ');
    });
    this.sysUpdaters = this.updaters.slice();

    // Network (network_info package)
    const net = store.has(E.wifiNetwork) || store.has(E.ipAddress1) ? card('Network') : null;
    if (net) {
      const n = (label, fn) => this.updaters.push(boundRow(net, label, fn));
      n('Wi-Fi network', () => store.text(E.wifiNetwork));
      n('Addresses', () => [E.ipAddress1, E.ipAddress2, E.ipAddress3, E.ipAddress4]
        .map(id => store.text(id)).filter(a => a && a !== '0.0.0.0').join(', '));
      if (store.has(E.wifiSignal)) {
        n('Signal', () => {
          const s = store.num(E.wifiSignal);
          if (isNaN(s)) return '';
          return `${s} dBm (${s >= -60 ? 'good' : s >= -70 ? 'fair' : 'weak'})`;
        });
      }
    }

    // Memory (diagnostics package)
    const mem = store.has(E.freeHeap) ? card('Memory') : null;
    if (mem) {
      const kb = id => () => isNaN(store.num(id)) ? '' : `${Math.round(store.num(id) / 1024)} KB`;
      const m = (label, fn) => this.updaters.push(boundRow(mem, label, fn));
      m('Free heap', kb(E.freeHeap));
      m('Largest free block', kb(E.largestBlock));
      m('Fragmentation', () => isNaN(store.num(E.fragmentation)) ? '' : `${store.num(E.fragmentation)} %`);
      m('Longest loop', () => isNaN(store.num(E.loopTime)) ? '' : `${store.num(E.loopTime)} ms`);
    }

    // Log
    this.paused = false;
    this.minLevel = 2;
    this.shownCount = Math.max(0, store.logCount - store.logLines.length);
    this.logBox = h('div', { class: 'log', role: 'log', 'aria-live': 'off', tabindex: '0' });
    const level = h('select', { class: 'input input-small', 'aria-label': 'Log level', onchange: () => {
      this.minLevel = +level.value;
      this.redrawLog();
    } }, h('option', { value: '4' }, 'Everything'), h('option', { value: '2', selected: true }, 'Info and above'),
         h('option', { value: '1' }, 'Warnings and errors'));
    const pause = h('button', { class: 'btn btn-small', onclick: () => {
      this.paused = !this.paused;
      setText(pause, this.paused ? 'Resume' : 'Pause');
      if (!this.paused) this.redrawLog();
    } }, 'Pause');
    const log = card('Log',
      h('div', { class: 'toolbar' }, level, pause,
        h('button', { class: 'btn btn-small', onclick: () => { this.clearedAt = store.logCount; this.redrawLog(); } }, 'Clear'),
        h('button', { class: 'btn btn-small', onclick: () => this.copyLog() }, icon('copy', 16), 'Copy')),
      this.logBox,
      h('p', { class: 'hint' }, 'Lines appear from when this page connected. The logger level in your YAML decides ' +
                                 'what the feeder sends (INFO by default).'));
    this.clearedAt = 0;

    // All entities
    this.filter = '';
    this.entityBox = h('div', { class: 'entities' });
    const search = h('input', { class: 'input', type: 'search', placeholder: 'Filter by name', 'aria-label': 'Filter entities',
                                oninput: () => { this.filter = search.value.trim().toLowerCase(); this.buildEntities(); } });
    const all = card('All entities', h('p', { class: 'hint' },
      'Everything this feeder reports, with a control for each. Changes act on the feeder straight away, ' +
      'through the same checks as everywhere else.'), search, this.entityBox);

    append(root, h('div', { class: 'grid' }, sys, net, mem), log, all);
    this.entityCount = -1;
    this.redrawLog();
    this.update(new Set(['*all']));
  },

  updateSystem() {
    for (const u of this.sysUpdaters) u();
  },

  update(changed) {
    for (const u of this.updaters) u();
    if (changed.has('*log') && !this.paused) this.appendLog();
    if (store.entities.size !== this.entityCount) this.buildEntities();
    else for (const id of changed) this.updateEntity(id);
  },

  unmount() {
    clearInterval(this.timer);
  },

  // ---- log ----
  logLine(entry) {
    const p = parseLogLine(entry.text);
    if ((LEVELS[p.level] ?? 2) > this.minLevel) return null;
    const time = new Date(entry.at).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' });
    return h('div', { class: `log-line log-${p.level || 'I'}` },
      h('span', { class: 'log-time' }, time), h('span', { class: 'log-level' }, p.level || '·'),
      p.tag ? h('span', { class: 'log-tag' }, p.tag) : null, h('span', { class: 'log-text' }, p.text));
  },
  visibleLines() {
    const first = store.logCount - store.logLines.length;  // count of the oldest line kept
    return store.logLines.filter((_, i) => first + i >= this.clearedAt);
  },
  redrawLog() {
    clear(this.logBox);
    const lines = this.visibleLines().map(l => this.logLine(l)).filter(Boolean);
    if (!lines.length) this.logBox.appendChild(h('p', { class: 'log-empty' }, 'No log lines yet.'));
    append(this.logBox, lines);
    this.shownCount = store.logCount;
    this.logBox.scrollTop = this.logBox.scrollHeight;
  },
  appendLog() {
    const atBottom = this.logBox.scrollHeight - this.logBox.scrollTop - this.logBox.clientHeight < 30;
    const first = store.logCount - store.logLines.length;
    const fresh = store.logLines.filter((_, i) => first + i >= Math.max(this.shownCount, this.clearedAt));
    this.shownCount = store.logCount;
    const empty = this.logBox.querySelector('.log-empty');
    for (const l of fresh) {
      const el = this.logLine(l);
      if (!el) continue;
      if (empty) empty.remove();
      this.logBox.appendChild(el);
    }
    while (this.logBox.childElementCount > 300) this.logBox.firstElementChild.remove();
    if (atBottom) this.logBox.scrollTop = this.logBox.scrollHeight;
  },
  copyLog() {
    const text = this.visibleLines().map(l => {
      const p = parseLogLine(l.text);
      return `${new Date(l.at).toLocaleTimeString()} [${p.level}][${p.tag}] ${p.text}`;
    }).join('\n');
    const done = () => toast('Log copied', 'ok');
    // The Clipboard API needs HTTPS; the feeder serves plain HTTP, so fall back to a hidden text box.
    if (navigator.clipboard && window.isSecureContext) {
      navigator.clipboard.writeText(text).then(done, toastError);
      return;
    }
    const area = h('textarea', { class: 'offscreen' });
    area.value = text;
    document.body.appendChild(area);
    area.select();
    try {
      document.execCommand('copy');
      done();
    } catch (err) {
      toast('Could not copy: select the log text instead', 'error');
    }
    area.remove();
  },

  // ---- all entities ----
  buildEntities() {
    this.entityCount = store.entities.size;
    this.rows = new Map();
    clear(this.entityBox);
    const groups = new Map();
    for (const [id, e] of store.entities) {
      const name = e.name || id;
      if (this.filter && !name.toLowerCase().includes(this.filter)) continue;
      const domain = e.domain || id.slice(0, id.indexOf('/'));
      if (!groups.has(domain)) groups.set(domain, []);
      groups.get(domain).push([id, e]);
    }
    for (const domain of Object.keys(DOMAIN_TITLES).concat([...groups.keys()].filter(d => !DOMAIN_TITLES[d]))) {
      const items = groups.get(domain);
      if (!items) continue;
      items.sort((a, b) => (a[1].name || a[0]).localeCompare(b[1].name || b[0]));
      const list = h('div', { class: 'entity-list' });
      for (const [id, e] of items) {
        const value = h('span', { class: 'entity-state' });
        const control = entityControl(id);
        const tags = [e.entity_category === 1 ? 'config' : null, e.entity_category === 2 ? 'diagnostic' : null,
                      e.is_disabled_by_default ? 'hidden in Home Assistant' : null].filter(Boolean);
        list.appendChild(h('div', { class: 'entity-row' },
          h('div', { class: 'entity-name' }, e.name || id, tags.length ? h('span', { class: 'tags' }, tags.join(' · ')) : null),
          domain === 'button' || domain === 'switch' ? null : value,
          control));
        this.rows.set(id, { value, control });
        this.updateEntity(id);
      }
      this.entityBox.appendChild(h('details', { class: 'entity-group', open: true },
        h('summary', {}, `${DOMAIN_TITLES[domain] || domain} (${items.length})`), list));
    }
    if (!groups.size) this.entityBox.appendChild(h('p', { class: 'hint' }, this.filter ? 'Nothing matches.' : 'Waiting for the feeder…'));
  },
  updateEntity(id) {
    const r = this.rows && this.rows.get(id);
    if (!r) return;
    const e = store.get(id);
    setText(r.value, e.state === undefined ? '' : e.state);
    if (r.control && r.control._update) r.control._update();
  },
};

// ---- app.js ----
// The shell: header, banner, tabs and routing, then start the connection. Tabs appear only for what this build
// contains (the entities each needs) and only once its page exists; nothing is configured in the app itself.

const TABS = [
  { id: 'dashboard', title: 'Dashboard', short: 'Home', icon: 'grid', shown: () => store.has(E.trayState) },
  { id: 'schedule', title: 'Schedule', short: 'Schedule', icon: 'calendar', shown: () => store.has(E.editProfile) },
  { id: 'configuration', title: 'Configuration', short: 'Config', icon: 'sliders', shown: () => store.has(E.dailyCap) },
  { id: 'maintenance', title: 'Maintenance', short: 'Service', icon: 'tool',
    shown: () => store.has(E.calibrationMode) || store.has(E.declarePosition) },
  { id: 'bluetooth', title: 'Bluetooth', short: 'BLE', icon: 'bluetooth', shown: () => store.has(E.bleSession) },
  { id: 'diagnostics', title: 'Diagnostics', short: 'Diag', icon: 'activity', shown: () => true },
];
// The initial list of entities arrives in a burst; it has settled once nothing new has come for this long.
const SETTLE_MS = 700;

const app = {
  current: null,  // {id, page}
  tabsKey: '',

  start() {
    // ESPHome's index page has no viewport tag, so phones would lay the page out 980 px wide and shrink it.
    if (!document.querySelector('meta[name="viewport"]')) {
      document.head.appendChild(h('meta', { name: 'viewport', content: 'width=device-width, initial-scale=1, viewport-fit=cover' }));
    }
    document.documentElement.lang = navigator.language || 'en';
    const root = document.querySelector('esp-app') || document.body;
    this.titleEl = h('span', { class: 'brand-name' }, 'Precision Feeder');
    this.clockEl = h('span', { class: 'header-clock' });
    this.connEl = h('span', { class: 'pill' });
    this.tabsEl = h('nav', { class: 'tabs', 'aria-label': 'Pages' });
    this.bannerEl = h('div', { class: 'banner-slot' });
    this.pageEl = h('main', { class: 'page', id: 'page', tabindex: '-1' });
    append(root,
      h('header', { class: 'header' },
        h('div', { class: 'header-inner' },
          h('span', { class: 'brand' }, icon('fish', 24), this.titleEl), h('span', { class: 'spacer' }),
          this.clockEl, this.connEl)),
      this.tabsEl,
      h('div', { class: 'container' }, this.bannerEl, this.pageEl),
      h('div', { id: 'toasts', class: 'toasts', 'aria-live': 'polite' }));
    banners.mount(this.bannerEl);
    window.addEventListener('hashchange', () => this.route());
    store.subscribe(changed => this.update(changed));
    store.start();
    this.update(new Set(['*all']));
    // Re-check the route once the first burst of entities has settled.
    const settle = setInterval(() => {
      if (this.settled()) {
        clearInterval(settle);
        this.update(new Set(['*settled']));
      }
    }, 200);
  },

  settled() {
    return store.status === 'online' && store.entities.size > 0 && Date.now() - store.lastNewEntity > SETTLE_MS;
  },

  visibleTabs() {
    return TABS.filter(t => PAGES[t.id] && t.shown());
  },

  update(changed) {
    this.updateHeader();
    this.updateTabs();
    banners.update();
    this.route();
    if (this.current && this.current.page.update) this.current.page.update(changed);
  },

  updateHeader() {
    const title = store.title || 'Precision Feeder';
    setText(this.titleEl, title);
    if (document.title !== title) document.title = title;
    const t = parseDeviceTime(store.text(E.deviceTime)) || parseLocalDateTime(store.text(E.deviceTime));
    setText(this.clockEl, t ? formatClock(t.hour, t.minute) : '');
    const online = store.status === 'online';
    setText(this.connEl, online ? 'Online' : store.everOnline ? 'Offline' : 'Connecting');
    this.connEl.className = `pill ${online ? 'pill-ok' : store.everOnline ? 'pill-danger' : 'pill-muted'}`;
  },

  updateTabs() {
    const tabs = this.visibleTabs();
    const active = this.current ? this.current.id : '';
    const key = tabs.map(t => t.id).join() + '|' + active;
    if (key === this.tabsKey) return;
    this.tabsKey = key;
    clear(this.tabsEl);
    for (const t of tabs) {
      this.tabsEl.appendChild(h('a', { href: `#${t.id}`, class: t.id === active ? 'tab tab-active' : 'tab',
                                      'aria-current': t.id === active ? 'page' : null },
        icon(t.icon, 20), h('span', { class: 'tab-long' }, t.title), h('span', { class: 'tab-short' }, t.short)));
    }
  },

  /** Show the page the address asks for, or the first one there is once the build is known. */
  route() {
    const [want, ...rest] = location.hash.replace(/^#/, '').split('/');
    const tabs = this.visibleTabs();
    let tab = tabs.find(t => t.id === want);
    if (!tab) {
      if (!this.settled()) {  // its entities may still be on their way
        if (!this.current) this.showLoading();
        return;
      }
      tab = tabs[0];
      if (want) history.replaceState(null, '', `#${tab.id}`);
    }
    const sub = rest.join('/');
    if (this.current && this.current.id === tab.id && this.current.sub === sub) return;
    if (this.current && this.current.page.unmount) this.current.page.unmount();
    clear(this.pageEl);
    this.current = { id: tab.id, sub, page: PAGES[tab.id] };
    this.current.page.mount(this.pageEl, sub);
    this.updateTabs();
  },

  showLoading() {
    if (this.pageEl.querySelector('.loading')) return;
    clear(this.pageEl);
    this.pageEl.appendChild(h('div', { class: 'loading' }, h('span', { class: 'spinner', 'aria-hidden': 'true' }),
      h('span', {}, 'Connecting to the feeder…')));
  },
};

app.start();
